                        text-anchor="middle" fill="#1e293b"
                        font-size="13" font-weight="800" font-family="Arial,sans-serif">
                    {{ fmtMln(lavinaDonutData.total) }}
                  </text>
                  <text :x="lavinaDonutData.cx" :y="lavinaDonutData.cy + 10"
                        text-anchor="middle" fill="#94a3b8"
                        font-size="9" font-weight="600" font-family="Arial,sans-serif">
                    {{ $t('results.total') }}
                  </text>
                  <template v-for="(seg, i) in lavinaDonutData.segs" :key="'l'+i">
                    <g v-if="seg.showInside">
                      <text :x="seg.lx" :y="seg.ly - 3"
                            text-anchor="middle" fill="#fff"
                            font-size="12" font-weight="800" font-family="Arial,sans-serif">
                        {{ seg.pct }}%
                      </text>
                      <text :x="seg.lx" :y="seg.ly + 10"
                            text-anchor="middle" fill="rgba(255,255,255,0.85)"
                            font-size="8" font-weight="600" font-family="Arial,sans-serif">
                        {{ (seg.item.category || '').slice(0,14) }}
                      </text>
                    </g>
                  </template>
                </svg>
              </div>

              <!-- Bars: 2 колонки -->
              <div class="lv-bars-grid">
                <div class="lv-cat-col">
                  <div v-for="item in lavinaCatHalves.left" :key="item.category" class="lv-cat-row">
                    <span class="lv-cat-dot" :style="{background: item.color}"></span>
                    <span class="lv-cat-name" :title="item.category">{{ item.category }}</span>
                    <div class="lv-cat-bar-outer">
                      <div class="lv-cat-bar-inner"
                           :style="{width: item.barW+'%', background: item.color}"></div>
                    </div>
                    <div class="lv-cat-right">
                      <span class="lv-cat-sum">{{ fmtShort(item.value) }}</span>
                      <span class="lv-cat-pct">{{ item.pct }}%</span>
                    </div>
                  </div>
                </div>
                <div class="lv-cat-col">
                  <div v-for="item in lavinaCatHalves.right" :key="item.category" class="lv-cat-row">
                    <span class="lv-cat-dot" :style="{background: item.color}"></span>
                    <span class="lv-cat-name" :title="item.category">{{ item.category }}</span>
                    <div class="lv-cat-bar-outer">
                      <div class="lv-cat-bar-inner"
                           :style="{width: item.barW+'%', background: item.color}"></div>
                    </div>
                    <div class="lv-cat-right">
                      <span class="lv-cat-sum">{{ fmtShort(item.value) }}</span>
                      <span class="lv-cat-pct">{{ item.pct }}%</span>
                    </div>
                  </div>
                </div>
              </div>

            </div>
          </div>
        </div>

      </div>

      <!-- ── Divider: кінець блока 6 ── -->
      <div class="rp-divider"></div>

    </div>
  </div>
</template>

<script>
/* eslint-disable */
import { markRaw } from 'vue'
import {
  Chart, BarElement, BarController, CategoryScale, LinearScale, Tooltip, Legend,
  DoughnutController, ArcElement, LineElement, LineController, PointElement,
} from 'chart.js'
Chart.register(BarElement, BarController, CategoryScale, LinearScale, Tooltip, Legend,
    DoughnutController, ArcElement, LineElement, LineController, PointElement)

import { dataStore }   from '@/operations/requests'
import { RESULTS_URL, getManagerColor } from '@/config/managers.config'

export default {
  name: 'ResultsPage',

  data() {
    return {
      loading:     true,
      error:       null,
      resultsData: null,
      screenWidth: typeof window !== 'undefined' ? window.innerWidth : 1024,
      charts:      {},
      catColors: [
        '#6366f1','#f59e0b','#22c55e','#ef4444','#14b8a6',
        '#f97316','#8b5cf6','#06b6d4','#84cc16','#ec4899','#64748b',
      ],
      selectedPeriod:  '',
      periodMenuOpen:  false,
      selectedRm:      '',
      _resizeTimer:    null,
    }
  },

  computed: {
    // ── Period ───────────────────────────────────────────
    availablePeriods() {
      const seen = new Set()
      return (this.resultsData?.main_kpi || [])
          .map(r => r.period)
          .filter(p => p && !seen.has(p) && seen.add(p))
    },

    period() {
      if (this.selectedPeriod) return this.selectedPeriod
      // Останній рядок main_kpi = найновіший period
      const rows = this.resultsData?.main_kpi || []
      return rows[rows.length - 1]?.period || ''
    },

    // ── Filtered data by period ───────────────────────────
    kpi() {
      const rows = this.resultsData?.main_kpi || []
      if (!Array.isArray(rows)) return rows  // backward compat
      return rows.find(r => r.period === this.period) || rows[rows.length - 1] || {}
    },
    credits()       { return (this.resultsData?.credits        || []).filter(r => r.period === this.period) },
    storesRevenue() { return (this.resultsData?.stores_revenue || []).filter(r => r.period === this.period) },

    isMobile() {
      return this.screenWidth < 640
    },

    // ── Gauge ────────────────────────────────────────────
    planColor() {
      const p = this.kpi.plan_pct || 0
      if (p >= 1.0) return '#22c55e'
      if (p >= 0.9) return '#f59e0b'
      return '#ef4444'
    },

    gaugeArcPath() {
      // Капаем на 0.999 чтобы избежать вырожденного случая pct=1.0 (start=end)
      const pct = Math.min(Math.max(this.kpi.plan_pct || 0, 0.001), 0.999)
      const cx = 100, cy = 100, r = 80
      const angle = Math.PI * (1 - pct)
      const x2 = cx + r * Math.cos(angle)
      const y2 = cy - r * Math.sin(angle)
      // largeArc всегда 0 — дуга заполнения никогда не превышает 180°
      return `M 20 100 A 80 80 0 0 1 ${x2.toFixed(2)} ${y2.toFixed(2)}`
    },

    // ── Credits ──────────────────────────────────────────
    ocList() {
      return this.credits
          .filter(c => c.oc_bank && c.oc_sum)
          .map(c => ({ name: c.oc_bank, amount: c.oc_sum }))
          .sort((a, b) => b.amount - a.amount)
    },

    creditBankList() {
      return this.credits
          .filter(c => c.bank && c.bank !== '-' && c.credit_sum)
          .map(c => ({ name: c.bank, amount: c.credit_sum }))
          .sort((a, b) => b.amount - a.amount)
    },

    totalCredit() {
      const oc = this.credits.reduce((s, c) => s + (c.oc_sum     || 0), 0)
      const cr = this.credits.reduce((s, c) => s + (c.credit_sum || 0), 0)
      return oc + cr
    },

    totalOC() {
      return this.credits.reduce((s, c) => s + (c.oc_sum || 0), 0)
    },

    totalCreditBanks() {
      return this.credits.reduce((s, c) => s + (c.credit_sum || 0), 0)
    },

    maxOC() {
      return Math.max(...this.ocList.map(i => i.amount), 1)
    },

    maxCredit() {
      return Math.max(...this.creditBankList.map(i => i.amount), 1)
    },

    // ── Lavina ────────────────────────────────────────────
    lavinaMain() {
      const data = this.resultsData?.lavina_main
      if (!data) return {}
      if (Array.isArray(data)) return data.find(r => r.period === this.period) || data[data.length - 1] || {}
      return data
    },
    lavinaCatRevenue() {
      return (this.resultsData?.lavina_cat_revenue || []).filter(r => r.period === this.period)
    },
    lavinaCatPlan() {
      return (this.resultsData?.lavina_cat_plan || [])
          .filter(r => r.period === this.period)
          .sort((a, b) => b.plan_pct - a.plan_pct)
    },
    lavinaPlanColor() {
      const p = this.lavinaMain.plan_pct || 0
      if (p >= 1.0) return '#22c55e'
      if (p >= 0.9) return '#f59e0b'
      return '#ef4444'
    },
    lavinaGaugeArcPath() {
      const pct = Math.min(Math.max(this.lavinaMain.plan_pct || 0, 0.001), 0.999)
      const cx = 100, cy = 100, r = 80
      const angle = Math.PI * (1 - pct)
      const x2 = cx + r * Math.cos(angle)
      const y2 = cy - r * Math.sin(angle)
      return `M 20 100 A 80 80 0 0 1 ${x2.toFixed(2)} ${y2.toFixed(2)}`
    },
    lavinaKpis() {
      const d = this.lavinaMain
      return [
        { label: this.$t('results.metrics.sumTO'),      value: this.fmtNum(d.revenue),      color: '#6366f1', bg: 'rgba(99,102,241,0.08)',  icon: '💰' },
        { label: this.$t('results.metrics.trafficShort'),value: this.fmtNum(d.avg_traffic),  color: '#14b8a6', bg: 'rgba(20,184,166,0.08)',  icon: '👣' },
        { label: this.$t('results.metrics.conversion'),  value: this.fmtConv(d.conversion),  color: '#3b82f6', bg: 'rgba(59,130,246,0.08)',  icon: '🔄' },
        { label: this.$t('results.metrics.avgCheck'),    value: this.fmtNum(d.avg_check),    color: '#f59e0b', bg: 'rgba(245,158,11,0.08)',  icon: '🧾' },
        { label: this.$t('results.metrics.credit'),      value: this.fmtConv(d.credit_pct),  color: '#22c55e', bg: 'rgba(34,197,94,0.08)',   icon: '💳' },
      ]
    },
    lavinaCatRevenueItems() {
      const total = this.lavinaCatRevenue.reduce((s, r) => s + (r.revenue || 0), 0)
      if (!total) return []
      const sorted = [...this.lavinaCatRevenue]
          .filter(r => r.revenue > 0)
          .sort((a, b) => b.revenue - a.revenue)
      const maxRev = sorted[0]?.revenue || 1
      return sorted.map((r, i) => ({
        category: r.category,
        value:    r.revenue,
        pct:      (r.revenue / total * 100).toFixed(2).replace('.', ','),
        barW:     r.revenue / maxRev * 100,
        color:    this.catColors[i % this.catColors.length],
      }))
    },
    lavinaDonutData() {
      const items = this.lavinaCatRevenueItems
      if (!items.length) return null
      const total = items.reduce((s, i) => s + i.value, 0)
      if (!total) return null
      const PI = Math.PI, cos = Math.cos, sin = Math.sin
      const W = 320, H = 320, cx = 160, cy = 160
      const R = 140, r = 82, push = 5, gap = 0.022
      const f = v => v.toFixed(2)
      let startA = -PI / 2
      const segs = items.map((item) => {
        const fullSweep = (item.value / total) * 2 * PI
        const sweep    = Math.max(fullSweep - gap * 2, 0.01)
        const sA = startA + gap, eA = sA + sweep, midA = sA + sweep / 2
        const dx = push * cos(midA), dy = push * sin(midA)
        const os = { x: cx+dx+R*cos(sA), y: cy+dy+R*sin(sA) }
        const oe = { x: cx+dx+R*cos(eA), y: cy+dy+R*sin(eA) }
        const is = { x: cx+dx+r*cos(sA), y: cy+dy+r*sin(sA) }
        const ie = { x: cx+dx+r*cos(eA), y: cy+dy+r*sin(eA) }
        const large = sweep > PI ? 1 : 0
        const path = [`M ${f(os.x)} ${f(os.y)}`,
          `A ${R} ${R} 0 ${large} 1 ${f(oe.x)} ${f(oe.y)}`,
          `L ${f(ie.x)} ${f(ie.y)}`,
          `A ${r} ${r} 0 ${large} 0 ${f(is.x)} ${f(is.y)}`, 'Z'].join(' ')
        const labelR  = (R + r) / 2
        const lx = cx + dx + labelR * cos(midA)
        const ly = cy + dy + labelR * sin(midA)
        const pct = (item.value / total * 100).toFixed(2).replace('.', ',')
        const showInside = (item.value / total * 100) >= 5
        startA += fullSweep
        return { item, path, pct, lx, ly, showInside }
      })
      return { segs, W, H, cx, cy, total }
    },
    lavinaCatHalves() {
      const items = this.lavinaCatRevenueItems
      const half  = Math.ceil(items.length / 2)
      return { left: items.slice(0, half), right: items.slice(half) }
    },

    // ── Stores detail ─────────────────────────────────────
    currentStoresDetail() {
      return (this.resultsData?.stores_detail || []).filter(r => r.period === this.period)
    },
    rmList() {
      const seen = new Set()
      return this.currentStoresDetail
          .map(s => s.rm)
          .filter(rm => rm && !seen.has(rm) && seen.add(rm))
    },
    selectedRmStores() {
      return this.currentStoresDetail.filter(s => s.rm === this.selectedRm)
    },
    storeChartH() {
      return Math.max(260, this.selectedRmStores.length * 22) + 'px'
    },

    // ── RM metrics ───────────────────────────────────────
    rmMetrics() {
      return (this.resultsData?.rm_metrics || []).filter(r => r.period === this.period)
    },
    rmBarHeight() {
      return Math.max(200, this.rmMetrics.length * 52) + 'px'
    },
    catManagers() {
      return (this.resultsData?.cat_managers || [])
          .filter(r => r.period === this.period && r.manager && r.manager !== 'СП')
    },
    catPlanRows() {
      return this.catManagers
          .filter(r => r.plan_pct > 0)
          .sort((a, b) => b.plan_pct - a.plan_pct)
    },
    catStockRows() {
      return this.catManagers
          .filter(r => r.stock)
          .sort((a, b) => b.stock - a.stock)
    },
    catTurnoverRows() {
      return this.catManagers
          .filter(r => r.turnover)
          .sort((a, b) => b.turnover - a.turnover)
    },
    catBarHeight() {
      return Math.max(280, this.catManagers.length * 32) + 'px'
    },
    catRevenueTreemap() { return this.buildCatTreemap(this.catRevenueLegend, this.isMobile) },
    catProfitTreemap()  { return this.buildCatTreemap(this.catProfitLegend,  this.isMobile) },
    totalCatRevenue() {
      return this.catManagers.filter(r => r.revenue).reduce((s, r) => s + r.revenue, 0)
    },
    totalCatProfit() {
      return this.catManagers.filter(r => r.profit).reduce((s, r) => s + r.profit, 0)
    },
    catRevenueLegend() {
      const rows   = this.catManagers.filter(r => r.revenue).sort((a, b) => b.revenue - a.revenue)
      const total  = rows.reduce((s, r) => s + r.revenue, 0)
      const maxVal = rows[0]?.revenue || 1
      return rows.map((r, i) => ({
        label: r.manager,
        value: r.revenue,
        pct:   total > 0 ? (r.revenue / total * 100).toFixed(1) : '0.0',
        barW:  r.revenue / maxVal * 100,
        color: this.catColors[i % this.catColors.length],
      }))
    },
    catProfitLegend() {
      const rows   = this.catManagers.filter(r => r.profit > 0).sort((a, b) => b.profit - a.profit)
      const total  = rows.reduce((s, r) => s + r.profit, 0)
      const maxVal = rows[0]?.profit || 1
      return rows.map((r, i) => ({
        label: r.manager,
        value: r.profit,
        pct:   total > 0 ? (r.profit / total * 100).toFixed(1) : '0.0',
        barW:  r.profit / maxVal * 100,
        color: this.catColors[i % this.catColors.length],
      }))
    },

    // ── YoY ──────────────────────────────────────────────
    yoyTotals() {
      const row = (this.resultsData?.yoy || [])
          .find(r => r.period === this.period && r.store === 'Ітогові')
      return { revenue: row?.revenue_yoy ?? null, traffic: row?.traffic_yoy ?? null }
    },

    yoyRevenue() {
      return (this.resultsData?.yoy || [])
          .filter(r => r.period === this.period && r.store !== 'Ітогові' && r.revenue_yoy != null)
          .sort((a, b) => b.revenue_yoy - a.revenue_yoy)
    },

    yoyTraffic() {
      return (this.resultsData?.yoy || [])
          .filter(r => r.period === this.period && r.store !== 'Ітогові' && r.traffic_yoy != null)
          .sort((a, b) => b.traffic_yoy - a.traffic_yoy)
    },

    yoyChartHeight() {
      return Math.max(400, Math.max(this.yoyRevenue.length, this.yoyTraffic.length) * 22) + 'px'
    },

    // ── Treemap ──────────────────────────────────────────
    treemapCells() {
      if (!this.storesRevenue.length) return []
      const n = this.storesRevenue.length
      const items = this.storesRevenue.map((s, i) => ({
        store:       s.store,
        value:       s.revenue,
        revenue:     s.revenue,
        _colorIdx:   i,
        _colorTotal: n,
      }))
      return this.computeTreemapLayout(items, this.isMobile)
    },
  },

  watch: {
    resultsData(val) {
      if (val && !this.selectedPeriod) {
        // Авто-вибір: останній рядок main_kpi = найновіший period
        const rows = val.main_kpi || []
        const lastPeriod = rows[rows.length - 1]?.period
        if (lastPeriod) this.selectedPeriod = lastPeriod
        // Якщо period не змінився (рядків немає) — ініціалізуємо графіки тут
        else this.$nextTick(() => this._initAllCharts())
      }
    },

    period() {
      this.$nextTick(() => this._initAllCharts())
    },
  },

  mounted() {
    const prev = localStorage.getItem('checkLoadStatus')
    this.loadData(prev)
    window.addEventListener('resize', this._onResize)
    document.addEventListener('click', this._onDocClick)
  },

  beforeUnmount() {
    window.removeEventListener('resize', this._onResize)
    document.removeEventListener('click', this._onDocClick)
    Object.values(this.charts).forEach(c => c && c.destroy())
  },

  methods: {

    // ── Data ─────────────────────────────────────────────
    async loadData(prevStatus) {
      this.loading = true
      this.error   = null
      try {
        const res  = await fetch(RESULTS_URL)
        const json = await res.json()
        dataStore.setResultsData(json.results_info)
        this.resultsData = json.results_info
      } catch {
        // При ошибке сети — пробуем отдать кеш
        const cached = dataStore.getResultsData()
        if (cached) {
          this.resultsData = cached
        } else {
          this.error = this.$t('results.loadError')
        }
      } finally {
        this.loading = false
        localStorage.setItem('checkLoadStatus', prevStatus || 'loaded')
      }
    },

    // ── RM charts ─────────────────────────────────────────
    _interpolateGradient(t) {
      // t: 0 = red, 0.5 = yellow, 1 = green
      t = Math.max(0, Math.min(1, t))
      let r, g, b
      if (t < 0.5) {
        const u = t * 2
        r = Math.round(239 + (234 - 239) * u)
        g = Math.round(68  + (179 - 68)  * u)
        b = Math.round(68  + (8   - 68)  * u)
      } else {
        const u = (t - 0.5) * 2
        r = Math.round(234 + (34  - 234) * u)
        g = Math.round(179 + (197 - 179) * u)
        b = Math.round(8   + (94  - 8)   * u)
      }
      return `rgb(${r},${g},${b})`
    },

    _rmColor(field, value) {
      // Для кожної метрики: red threshold, yellow threshold, green threshold
      const cfg = {
        plan_pct:           { red: 0.80, yellow: 0.90, green: 1.15 },
        stores_on_plan_pct: { red: 0.20, yellow: 0.50, green: 0.85 },
        categories_pct:     { red: 0.20, yellow: 0.50, green: 1.00 },
        sellers_ke_pct:     { red: 0.10, yellow: 0.30, green: 0.70 },
        avg_check:          { red: 2000,  yellow: 3500,  green: 5500  },
        conversion:         { red: 0.15, yellow: 0.20, green: 0.28 },
      }[field]

      if (!cfg) return '#22c55e'

      let t
      if (value <= cfg.yellow) {
        t = ((value - cfg.red) / (cfg.yellow - cfg.red)) * 0.5
      } else {
        t = 0.5 + ((value - cfg.yellow) / (cfg.green - cfg.yellow)) * 0.5
      }
      return this._interpolateGradient(t)
    },

    _rmSort(field) {
      return [...this.rmMetrics]
          .filter(r => r[field] != null)
          .sort((a, b) => b[field] - a[field])
    },

    initRmCharts() {
      // % показники
      const pctCharts = [
        { ref: 'chartRmPlan',    field: 'plan_pct',           fmt: v => (v * 100).toFixed(1) + ' %' },
        { ref: 'chartRmStores',  field: 'stores_on_plan_pct', fmt: v => (v * 100).toFixed(1) + '%'  },
        { ref: 'chartRmCat',     field: 'categories_pct',     fmt: v => (v * 100).toFixed(1) + '%'  },
        { ref: 'chartRmSellers', field: 'sellers_ke_pct',     fmt: v => (v * 100).toFixed(1) + ' %' },
        { ref: 'chartRmConv',    field: 'conversion',         fmt: v => (v * 100).toFixed(1) + ' %' },
      ]
      pctCharts.forEach(({ ref, field, fmt }) => {
        const rows = this._rmSort(field)
        this.makeCatBar(ref,
            rows.map(r => r.rm),
            rows.map(r => r[field]),
            rows.map(r => this._rmColor(field, r[field])),
            { fmt, xFmt: v => (v * 100).toFixed(0) + '%' },
        )
      })

      // Середній чек
      const checkRows = this._rmSort('avg_check')
      this.makeCatBar('chartRmCheck',
          checkRows.map(r => r.rm),
          checkRows.map(r => r.avg_check),
          checkRows.map(r => this._rmColor('avg_check', r.avg_check)),
          { fmt: v => Math.round(v).toLocaleString('uk-UA'),
            xFmt: v => (v / 1000).toFixed(1) + 'т' },
      )
    },

    // ── YoY charts ────────────────────────────────────────
    initYoyCharts() {
      if (!this.yoyRevenue.length && !this.yoyTraffic.length) return
      const revVals  = this.yoyRevenue.map(r => r.revenue_yoy)
      const trafVals = this.yoyTraffic.map(r => r.traffic_yoy)
      const revMin  = revVals.length  ? Math.min(...revVals)  : 0
      const revMax  = revVals.length  ? Math.max(...revVals)  : 1
      const trafMin = trafVals.length ? Math.min(...trafVals) : 0
      const trafMax = trafVals.length ? Math.max(...trafVals) : 1

      this.makeHBar(
          'chartYoyRevenue',
          this.yoyRevenue.map(r => r.store),
          this.yoyRevenue.map(r => r.revenue_yoy),
          this.yoyRevenue.map(r => this._yoyGradientColor(r.revenue_yoy, revMin, revMax, 0.04)),
      )
      this.makeHBar(
          'chartYoyTraffic',
          this.yoyTraffic.map(r => r.store),
          this.yoyTraffic.map(r => r.traffic_yoy),
          this.yoyTraffic.map(r => this._yoyGradientColor(r.traffic_yoy, trafMin, trafMax, 0.05)),
      )
    },

    _yoyGradientColor(value, minVal, maxVal, yellowCenter) {
      if (value == null) return 'rgba(148,163,184,0.6)'
      let t
      if (value <= yellowCenter) {
        t = minVal === yellowCenter ? 0 : ((value - minVal) / (yellowCenter - minVal)) * 0.5
      } else {
        t = maxVal === yellowCenter ? 1 : 0.5 + ((value - yellowCenter) / (maxVal - yellowCenter)) * 0.5
      }
      return this._interpolateGradient(t)
    },

    makeHBar(ref, labels, data, colors) {
      const canvas = this.$refs[ref]
      if (!canvas) return
      if (this.charts[ref]) { this.charts[ref].destroy(); this.charts[ref] = null }

      const fmtPct = v => (v >= 0 ? '+' : '') + (v * 100).toFixed(1) + '%'

      const datalabels = {
        id: 'yoy_labels_' + ref,
        afterDatasetsDraw(chart) {
          const { ctx } = chart
          chart.data.datasets.forEach((ds, dsIdx) => {
            chart.getDatasetMeta(dsIdx).data.forEach((bar, idx) => {
              const v = ds.data[idx]
              if (v == null) return
              ctx.save()
              ctx.fillStyle    = '#334155'
              ctx.font         = 'bold 9px Arial, sans-serif'
              ctx.textAlign    = v >= 0 ? 'left' : 'right'
              ctx.textBaseline = 'middle'
              ctx.fillText(fmtPct(v), v >= 0 ? bar.x + 4 : bar.x - 4, bar.y)
              ctx.restore()
            })
          })
        },
      }

      this.charts[ref] = markRaw(new Chart(canvas, {
        type: 'bar',
        data: {
          labels,
          datasets: [{ data, backgroundColor: colors, borderRadius: 4, borderSkipped: false }],
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { top: 8, right: 56, left: 4, bottom: 8 } },
          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.9)',
              padding: 10, cornerRadius: 8,
              callbacks: { label: ctx => '  ' + fmtPct(ctx.raw) },
            },
          },
          scales: {
            x: {
              grid: { color: 'rgba(0,0,0,0.05)' },
              ticks: { font: { size: 10 }, color: '#64748b', callback: v => fmtPct(v) },
            },
            y: {
              grid: { display: false },
              ticks: { font: { size: 10, weight: 'normal' }, color: '#475569', crossAlign: 'far' },
            },
          },
        },
        plugins: [datalabels],
      }))
    },

    // ── Cat managers charts ───────────────────────────────
    initCatCharts() {
      const colors = this.catColors

      // 1. Виконання прибутку
      const planRows = this.catPlanRows
      this.makeCatBar('chartCatPlan',
          planRows.map(r => r.manager),
          planRows.map(r => r.plan_pct),
          planRows.map(r => {
            const p = r.plan_pct
            if (p >= 1.1)  return '#15803d'  // темно-зелений
            if (p >= 1.05) return '#16a34a'  // зелений
            if (p >= 1.0)  return '#22c55e'  // яскраво-зелений
            if (p >= 0.95) return '#4ade80'  // середньо-зелений
            if (p >= 0.90) return '#86efac'  // м'яко-зелений
            if (p >= 0.80) return '#eab308'  // жовтий
            return '#f97316'                  // помаранчевий
          }),
          { fmt: v => (v * 100).toFixed(1) + ' %', xFmt: v => (v * 100).toFixed(0) + '%' },
      )

      // 2. Сток
      const stockRows = this.catStockRows
      const maxStock = stockRows[0]?.stock || 1
      this.makeCatBar('chartCatStock',
          stockRows.map(r => r.manager),
          stockRows.map(r => r.stock),
          stockRows.map(r => r.stock === maxStock
              ? 'rgba(13,148,136,0.92)'
              : 'rgba(20,184,166,0.75)'),
          { fmt: v => Math.round(v).toLocaleString('uk-UA'),
            xFmt: v => Math.abs(v) >= 1e6 ? (v/1e6).toFixed(0)+'м' : (v/1e3).toFixed(0)+'т' },
      )

      // 3. Оборотність
      const turnRows = this.catTurnoverRows
      this.makeCatBar('chartCatTurnover',
          turnRows.map(r => r.manager),
          turnRows.map(r => r.turnover),
          turnRows.map(r => r.turnover > 100
              ? 'rgba(67,56,202,0.85)'
              : 'rgba(99,102,241,0.70)'),
          { fmt: v => String(Math.round(v)), xFmt: v => String(Math.round(v)) },
      )

      // 4 і 5. Структура доходу/прибутку — SVG через buildPie3d (не Chart.js)
    },

    makeCatBar(ref, labels, data, colors, opts = {}) {
      const canvas = this.$refs[ref]
      if (!canvas) return
      if (this.charts[ref]) { this.charts[ref].destroy(); this.charts[ref] = null }

      const fmt  = opts.fmt  || (v => String(v))
      const xFmt = opts.xFmt || fmt

      const datalabels = {
        id: 'cat_labels_' + ref,
        afterDatasetsDraw(chart) {
          const { ctx } = chart
          chart.data.datasets.forEach((ds, dsIdx) => {
            chart.getDatasetMeta(dsIdx).data.forEach((bar, idx) => {
              const v = ds.data[idx]
              if (v == null) return
              ctx.save()
              ctx.fillStyle    = '#334155'
              ctx.font         = 'bold 9px Arial, sans-serif'
              ctx.textAlign    = v >= 0 ? 'left' : 'right'
              ctx.textBaseline = 'middle'
              ctx.fillText(fmt(v), v >= 0 ? bar.x + 5 : bar.x - 5, bar.y)
              ctx.restore()
            })
          })
        },
      }

      this.charts[ref] = markRaw(new Chart(canvas, {
        type: 'bar',
        data: {
          labels,
          datasets: [{ data, backgroundColor: colors, borderRadius: 4, borderSkipped: false }],
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { top: 8, right: 70, left: 4, bottom: 8 } },
          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.9)',
              padding: 10, cornerRadius: 8,
              callbacks: { label: ctx => '  ' + fmt(ctx.raw) },
            },
          },
          scales: {
            x: {
              grid: { color: 'rgba(0,0,0,0.05)' },
              ticks: { font: { size: 10 }, color: '#64748b', callback: xFmt },
            },
            y: {
              grid: { display: false },
              ticks: { font: { size: 10, weight: 'normal' }, color: '#475569', crossAlign: 'far' },
            },
          },
        },
        plugins: [datalabels],
      }))
    },

    // ── Cat treemap (landscape desktop / portrait mobile) ─
    buildCatTreemap(items, mobile = false) {
      if (!items.length) return []
      const W = mobile ? 500 : 1000
      const H = mobile ? 800 : 500
      const total = items.reduce((s, i) => s + i.value, 0)
      if (!total) return []
      const normed = items.map(i => ({
        ...i,
        _area: (i.value / total) * W * H,
      }))
      const result = []
      this._tmSquarify(normed, 0, 0, W, H, result)
      return result.map(r => ({
        label: r.label,
        value: r.value,
        pct:   (r.value / total * 100).toFixed(1),
        color: r.color,
        xPct:  r._x / W * 100,
        yPct:  r._y / H * 100,
        wPct:  r._w / W * 100,
        hPct:  r._h / H * 100,
        w:     r._w,
        h:     r._h,
      }))
    },

    // ── Helpers ───────────────────────────────────────────
    _initAllCharts() {
      this.initYoyCharts()
      this.initCatCharts()
      this.initRmCharts()
      if (this.rmList.length && !this.rmList.includes(this.selectedRm)) {
        this.selectedRm = this.rmList[0]
      }
      this.$nextTick(() => {
        this.initRmStoreCharts()
        this.initLavinaCharts()
      })
    },

    // ── Блок 5: Stores charts ─────────────────────────────
    rmColor(rm) {
      return getManagerColor(rm) || '#94a3b8'
    },

    rmStoreCount(rm) {
      return this.currentStoresDetail.filter(s => s.rm === rm).length
    },

    selectRm(rm) {
      this.selectedRm = rm
      this.$nextTick(() => this.initRmStoreCharts())
    },

    initRmStoreCharts() {
      if (!this.rmList.length) return
      if (!this.selectedRm || !this.rmList.includes(this.selectedRm)) {
        this.selectedRm = this.rmList[0]
      }
      const stores = this.selectedRmStores
      if (!stores.length) return

      const sortBy = (field) => [...stores]
          .filter(s => s[field] != null)
          .sort((a, b) => b[field] - a[field])

      // 1. Виконання плану
      const planRows = sortBy('plan_pct')
      this.makeCatBar('chartRmStorePlan',
          planRows.map(s => s.store),
          planRows.map(s => s.plan_pct),
          planRows.map(s => this._storeColor('plan_pct', s.plan_pct)),
          { fmt: v => (v * 100).toFixed(1) + ' %', xFmt: v => (v*100).toFixed(0)+'%' },
      )

      // 2. Товарообіг
      const revRows  = sortBy('revenue')
      const maxRev   = revRows[0]?.revenue || 1
      this.makeCatBar('chartRmStoreRev',
          revRows.map(s => s.store),
          revRows.map(s => s.revenue),
          revRows.map(s => this._storeColor('revenue', s.revenue, maxRev)),
          { fmt: v => Math.round(v).toLocaleString('uk-UA'),
            xFmt: v => (v/1e6).toFixed(1)+'м' },
      )

      // 3. % категорій
      const catRows = sortBy('cat_pct')
      this.makeCatBar('chartRmStoreCat',
          catRows.map(s => s.store),
          catRows.map(s => s.cat_pct),
          catRows.map(s => this._storeColor('cat_pct', s.cat_pct)),
          { fmt: v => (v * 100).toFixed(1) + ' %', xFmt: v => (v*100).toFixed(0)+'%' },
      )

      // 4. Прибуток
      const profRows  = sortBy('profit')
      const maxProfit = Math.max(...profRows.map(s => s.profit), 0)
      this.makeCatBar('chartRmStoreProfit',
          profRows.map(s => s.store),
          profRows.map(s => s.profit),
          profRows.map(s => this._storeColor('profit', s.profit, maxProfit)),
          { fmt: v => Math.round(v).toLocaleString('uk-UA'),
            xFmt: v => (v/1e3).toFixed(0)+'т' },
      )

      // 5. Трафік і конверсія
      const trafRows = [...stores]
          .filter(s => s.avg_traffic != null)
          .sort((a, b) => b.avg_traffic - a.avg_traffic)
      this.makeTrafficConvChart('chartRmStoreTraffic', trafRows)

      // 6. Середній чек
      const checkRows = sortBy('avg_check')
      this.makeCatBar('chartRmStoreCheck',
          checkRows.map(s => s.store),
          checkRows.map(s => s.avg_check),
          checkRows.map(s => this._storeColor('avg_check', s.avg_check)),
          { fmt: v => Math.round(v).toLocaleString('uk-UA'),
            xFmt: v => (v/1e3).toFixed(1)+'т' },
      )

      // 7. Кредитування
      const creditRows = sortBy('credit_pct')
      this.makeCatBar('chartRmStoreCredit',
          creditRows.map(s => s.store),
          creditRows.map(s => s.credit_pct),
          creditRows.map(s => this._storeColor('credit_pct', s.credit_pct)),
          { fmt: v => (v * 100).toFixed(1) + ' %', xFmt: v => (v*100).toFixed(0)+'%' },
      )
    },

    makeTrafficConvChart(ref, stores) {
      const canvas = this.$refs[ref]
      if (!canvas) return
      if (this.charts[ref]) { this.charts[ref].destroy(); this.charts[ref] = null }

      const labels  = stores.map(s => s.store.length > 14 ? s.store.slice(0,13)+'…' : s.store)
      const traffic = stores.map(s => s.avg_traffic)
      const conv    = stores.map(s => s.conversion)
      const tColors = traffic.map(v => this._storeColor('avg_traffic', v))

      const labelsPlugin = {
        id: 'trafConvLabels_' + ref,
        afterDatasetsDraw(chart) {
          const { ctx } = chart
          // Traffic values inside bars
          const meta0 = chart.getDatasetMeta(0)
          meta0.data.forEach((bar, i) => {
            const v = traffic[i]; if (!v) return
            ctx.save()
            ctx.fillStyle = '#fff'
            ctx.font = 'bold 10px Arial,sans-serif'
            ctx.textAlign = 'center'
            ctx.textBaseline = 'bottom'
            ctx.fillText(v, bar.x, bar.base - 4)
            ctx.restore()
          })
          // Conversion % above line points
          const meta1 = chart.getDatasetMeta(1)
          meta1.data.forEach((pt, i) => {
            const v = conv[i]; if (!v) return
            ctx.save()
            ctx.fillStyle = '#475569'
            ctx.font = 'bold 10px Arial,sans-serif'
            ctx.textAlign = 'center'
            ctx.textBaseline = 'bottom'
            ctx.fillText((v * 100).toFixed(1) + '%', pt.x, pt.y - 4)
            ctx.restore()
          })
        },
      }

      this.charts[ref] = markRaw(new Chart(canvas, {
        type: 'bar',
        data: {
          labels,
          datasets: [
            {
              type: 'bar',
              data: traffic,
              backgroundColor: tColors,
              borderRadius: 4,
              yAxisID: 'y',
              order: 2,
            },
            {
              type: 'line',
              data: conv,
              borderColor: '#6366f1',
              backgroundColor: 'rgba(99,102,241,0.08)',
              pointBackgroundColor: '#6366f1',
              pointBorderColor: '#fff',
              pointBorderWidth: 2,
              pointRadius: 5,
              borderWidth: 2.5,
              tension: 0.3,
              yAxisID: 'y1',
              order: 1,
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'index' },
          layout: { padding: { top: 28, bottom: 4, left: 4, right: 4 } },
          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.9)',
              padding: 10, cornerRadius: 8,
              callbacks: {
                label: ctx => ctx.datasetIndex === 0
                    ? `  ${this.$t('results.metrics.trafficShort')}: ${ctx.raw}`
                    : `  ${this.$t('results.metrics.conversion')}: ${(ctx.raw * 100).toFixed(1)}%`,
              },
            },
          },
          scales: {
            x: {
              grid: { display: false },
              ticks: { font: { size: 9, weight: 'normal' }, color: '#475569',
                maxRotation: 45, crossAlign: 'far' },
            },
            y: {
              grid: { color: 'rgba(0,0,0,0.05)' },
              ticks: { font: { size: 10 }, color: '#64748b' },
            },
            y1: {
              position: 'right',
              grid: { display: false },
              ticks: { font: { size: 10 }, color: '#6366f1',
                callback: v => (v * 100).toFixed(0) + '%' },
            },
          },
        },
        plugins: [labelsPlugin],
      }))
    },

    _storeColor(field, value, maxVal) {
      if (value == null) return 'rgba(148,163,184,0.5)'
      switch (field) {
        case 'plan_pct':
          return this._interpolateGradient(this._gradNorm(value, 0.80, 0.90, 1.15))
        case 'revenue': {
          const r = value / Math.max(maxVal, 1)
          if (r > 0.80) return '#15803d'
          if (r > 0.50) return '#22c55e'
          if (r > 0.30) return '#4ade80'
          if (r > 0.15) return '#86efac'
          return '#bbf7d0'
        }
        case 'cat_pct':
          return this._interpolateGradient(this._gradNorm(value, 0.20, 0.49, 1.00))
        case 'profit':
          if (value < 0) return '#ef4444'
          return this._interpolateGradient(0.5 + (value / Math.max(maxVal, 1)) * 0.5)
        case 'avg_traffic':
          return this._interpolateGradient(this._gradNorm(value, 0, 50, 120))
        case 'avg_check':
          return this._interpolateGradient(this._gradNorm(value, 2000, 2999, 8000))
        case 'credit_pct':
          return this._interpolateGradient(this._gradNorm(value, 0.10, 0.213, 0.50))
        default:
          return '#22c55e'
      }
    },

    _gradNorm(value, redVal, yellowVal, greenVal) {
      let t
      if (value <= yellowVal) {
        t = redVal === yellowVal ? 0
            : ((value - redVal) / (yellowVal - redVal)) * 0.5
      } else {
        t = greenVal === yellowVal ? 1
            : 0.5 + ((value - yellowVal) / (greenVal - yellowVal)) * 0.5
      }
      return Math.max(0, Math.min(1, t))
    },

    // ── Блок 6: Lavina ────────────────────────────────────
    initLavinaCharts() {
      // Блок Лавина наразі не має Chart.js графіків (тільки SVG donut + div bars)
    },

    _onResize() {
      this.screenWidth = window.innerWidth
      clearTimeout(this._resizeTimer)
      this._resizeTimer = setTimeout(() => {
        Object.values(this.charts).forEach(c => c && c.resize())
      }, 150)
    },

    _onDocClick(e) {
      const wrap = this.$el?.querySelector('.period-wrap')
      if (wrap && !wrap.contains(e.target)) {
        this.periodMenuOpen = false
      }
    },

    // ── Treemap (1:1 как в BudgetPage) ───────────────────
    computeTreemapLayout(items, mobile = false) {
      if (!items.length) return []
      const W = mobile ? 500 : 1000
      const H = mobile ? 800 : 500
      const total = items.reduce((s, i) => s + i.value, 0)
      if (!total) return []
      const normed = items.map(i => ({
        ...i,
        _area: (i.value / total) * W * H,
        color: this._tmColor(i._colorIdx, i._colorTotal),
      }))
      const result = []
      this._tmSquarify(normed, 0, 0, W, H, result)
      return result.map(r => ({
        store:   r.store,
        revenue: r.revenue,
        color:   r.color,
        xPct:    r._x / W * 100,
        yPct:    r._y / H * 100,
        wPct:    r._w / W * 100,
        hPct:    r._h / H * 100,
      }))
    },

    _tmColor(rank, total) {
      // green (#22c55e) → yellow (~#eab308) → red (#ef4444)
      const t = rank / Math.max(total - 1, 1)
      let r, g, b
      if (t < 0.5) {
        const u = t * 2
        r = Math.round(34  + (234 - 34)  * u)
        g = Math.round(197 + (179 - 197) * u)
        b = Math.round(94  + (8   - 94)  * u)
      } else {
        const u = (t - 0.5) * 2
        r = Math.round(234 + (239 - 234) * u)
        g = Math.round(179 + (68  - 179) * u)
        b = Math.round(8   + (68  - 8)   * u)
      }
      return `rgb(${r},${g},${b})`
    },

    _tmWorst(row, side) {
      if (!row.length || !side) return Infinity
      const s  = row.reduce((a, i) => a + i._area, 0)
      const mx = Math.max(...row.map(i => i._area))
      const mn = Math.min(...row.map(i => i._area))
      return Math.max(side * side * mx / (s * s), s * s / (side * side * mn))
    },

    _tmSquarify(items, x, y, w, h, out) {
      if (!items.length) return
      if (w < 1 || h < 1) return
      if (items.length === 1) {
        out.push({...items[0], _x: x, _y: y, _w: w, _h: h})
        return
      }
      const side   = Math.min(w, h)
      const isWide = w >= h
      let row  = []
      let rest = [...items]

      while (rest.length) {
        const next   = rest[0]
        const newRow = [...row, next]
        if (!row.length || this._tmWorst(newRow, side) <= this._tmWorst(row, side)) {
          row.push(next)
          rest.shift()
        } else {
          break
        }
      }

      // Если ничего не добавилось — берём первый принудительно
      if (!row.length) { row.push(rest.shift()) }

      const rowArea = row.reduce((s, i) => s + i._area, 0)

      if (isWide) {
        const colW = rowArea / h
        let py = y
        for (const item of row) {
          const ch = item._area / colW
          out.push({...item, _x: x, _y: py, _w: colW, _h: ch})
          py += ch
        }
        if (rest.length) this._tmSquarify(rest, x + colW, y, w - colW, h, out)
      } else {
        const rowH = rowArea / w
        let px = x
        for (const item of row) {
          const cw = item._area / rowH
          out.push({...item, _x: px, _y: y, _w: cw, _h: rowH})
          px += cw
        }
        if (rest.length) this._tmSquarify(rest, x, y + rowH, w, h - rowH, out)
      }
    },

    // ── Formatting ────────────────────────────────────────
    fmtNum(n) {
      if (n == null || n === '') return '—'
      return Math.round(n).toLocaleString('uk-UA')
    },

    fmtShort(n) {
      if (n == null) return ''
      if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + ' млн'
      if (n >= 1_000)     return (n / 1_000).toFixed(0)     + ' тис'
      return Math.round(n).toString()
    },

    fmtPlanPct(p) {
      if (p == null) return '—'
      return (p * 100).toFixed(1).replace('.', ',') + ' %'
    },

    fmtConv(p) {
      if (p == null) return '—'
      return (p * 100).toFixed(1).replace('.', ',') + '%'
    },

    fmtMln(n) {
      if (!n) return '0'
      return (n / 1_000_000).toFixed(2).replace('.', ',') + ' млн'
    },

    fmtYoy(v) {
      if (v == null) return '—'
      const sign = v >= 0 ? '+' : ''
      return sign + (v * 100).toFixed(1).replace('.', ',') + '%'
    },

    sharePct(val, total) {
      if (!total) return '0,0'
      return (val / total * 100).toFixed(1).replace('.', ',')
    },

    barPct(val, max) {
      return Math.round((val / max) * 100)
    },
  },
}
</script>

